import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    invoices_df = inputs["invoices"].copy()
    payments_df = inputs["payments"].copy()

    # Initialize tracking structures
    # For each invoice, track its open_amount
    open_amounts = {row['invoice_id']: row['amount'] for _, row in invoices_df.iterrows()}

    # For each invoice, track how much has been applied
    invoice_applied = {inv_id: 0.0 for inv_id in invoices_df['invoice_id']}

    # Allocations list: (payment_id, invoice_id, applied_amount)
    allocations = []

    # Customer credit: customer_id -> unapplied_amount
    customer_credit = {}

    # Group invoices by customer
    invoices_by_customer = {}
    for _, row in invoices_df.iterrows():
        cust_id = row['customer_id']
        if cust_id not in invoices_by_customer:
            invoices_by_customer[cust_id] = []
        invoices_by_customer[cust_id].append(row)

    # Sort invoices by due_date, then invoice_id (oldest first)
    for cust_id in invoices_by_customer:
        invoices_by_customer[cust_id].sort(
            key=lambda x: (x['due_date'], x['invoice_id'])
        )

    # Sort payments by customer, then paid_ts, then payment_id
    payments_by_customer = {}
    for _, row in payments_df.iterrows():
        cust_id = row['customer_id']
        if cust_id not in payments_by_customer:
            payments_by_customer[cust_id] = []
        payments_by_customer[cust_id].append(row)

    for cust_id in payments_by_customer:
        payments_by_customer[cust_id].sort(
            key=lambda x: (x['paid_ts'], x['payment_id'])
        )

    # Process each customer's payments
    for cust_id in payments_by_customer:
        customer_credit[cust_id] = 0.0

        # Get invoices for this customer
        cust_invoices = invoices_by_customer.get(cust_id, [])

        # Process each payment for this customer
        for payment_row in payments_by_customer[cust_id]:
            payment_id = payment_row['payment_id']
            left = payment_row['amount']

            # Apply payment to invoices in order
            for invoice_row in cust_invoices:
                invoice_id = invoice_row['invoice_id']
                current_open = open_amounts[invoice_id]

                if current_open > 0:
                    # Pay the minimum of what's left and what's open
                    pay = min(left, current_open)

                    open_amounts[invoice_id] -= pay
                    invoice_applied[invoice_id] += pay
                    left -= pay

                    allocations.append({
                        'payment_id': payment_id,
                        'invoice_id': invoice_id,
                        'applied_amount': pay
                    })

                    if left == 0:
                        break

            # Any remaining amount becomes unapplied credit
            customer_credit[cust_id] += left

    # Build invoice_status output
    invoice_status_rows = []
    for _, invoice_row in invoices_df.iterrows():
        invoice_id = invoice_row['invoice_id']
        open_amt = open_amounts[invoice_id]
        applied_amt = invoice_applied[invoice_id]

        # Determine status
        if open_amt == 0:
            status = 'PAID'
        elif applied_amt == 0:
            status = 'OPEN'
        else:
            status = 'PARTIAL'

        invoice_status_rows.append({
            'invoice_id': invoice_id,
            'open_amount': open_amt,
            'status': status
        })

    invoice_status = pd.DataFrame(invoice_status_rows)

    # Build allocations output
    if allocations:
        allocations_df = pd.DataFrame(allocations)
    else:
        allocations_df = pd.DataFrame(columns=['payment_id', 'invoice_id', 'applied_amount'])

    # Build customer_credit output (only include non-zero)
    customer_credit_rows = []
    for cust_id, unapplied in customer_credit.items():
        if unapplied > 0:
            customer_credit_rows.append({
                'customer_id': cust_id,
                'unapplied_amount': unapplied
            })

    if customer_credit_rows:
        customer_credit_df = pd.DataFrame(customer_credit_rows)
    else:
        customer_credit_df = pd.DataFrame(columns=['customer_id', 'unapplied_amount'])

    # Ensure correct dtypes
    if not invoice_status.empty:
        invoice_status['invoice_id'] = invoice_status['invoice_id'].astype('int64')
        invoice_status['open_amount'] = invoice_status['open_amount'].astype('float64')

    if not allocations_df.empty:
        allocations_df['payment_id'] = allocations_df['payment_id'].astype('int64')
        allocations_df['invoice_id'] = allocations_df['invoice_id'].astype('int64')
        allocations_df['applied_amount'] = allocations_df['applied_amount'].astype('float64')

    if not customer_credit_df.empty:
        customer_credit_df['customer_id'] = customer_credit_df['customer_id'].astype('int64')
        customer_credit_df['unapplied_amount'] = customer_credit_df['unapplied_amount'].astype('float64')

    return {
        'invoice_status': invoice_status,
        'allocations': allocations_df,
        'customer_credit': customer_credit_df
    }
